{
  "items": [
    {
      "name": "Finsupp.weight_apply",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {M : Type u_2} {R : Type u_3} [inst : Semiring R] (w : σ → M) [inst_1 : AddCommMonoid M]\n  [inst_2 : Module R M] (f : σ →₀ R), (Finsupp.weight w) f = f.sum fun i c => c • w i"
    },
    {
      "name": "Rat.cast_finsupp_sum",
      "module_name": "Mathlib.Data.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_5} {R : Type u_10} [inst : Zero M] (f : α →₀ M) [inst_1 : DivisionRing R] [CharZero R]\n  (g : α → M → ℚ), ↑(f.sum g) = f.sum fun a b => ↑(g a b)"
    },
    {
      "name": "Finsupp.weight_single",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {M : Type u_2} {R : Type u_3} [inst : Semiring R] (w : σ → M) [inst_1 : AddCommMonoid M]\n  [inst_2 : Module R M] (s : σ) (r : R), (Finsupp.weight w) (Finsupp.single s r) = r • w s"
    },
    {
      "name": "IsLocalizedModule.commonDenomOfFinset",
      "module_name": "Mathlib.Algebra.Module.LocalizedModule.Int",
      "kind": "definition",
      "type": "{R : Type u_1} →\n  [inst : CommSemiring R] →\n    (S : Submonoid R) →\n      {M : Type u_2} →\n        [inst_1 : AddCommMonoid M] →\n          [inst_2 : Module R M] →\n            {M' : Type u_3} →\n              [inst_3 : AddCommMonoid M'] →\n                [inst_4 : Module R M'] → (f : M →ₗ[R] M') → [IsLocalizedModule S f] → Finset M' → ↥S"
    },
    {
      "name": "Finsupp.weight",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "definition",
      "type": "{σ : Type u_1} →\n  {M : Type u_2} →\n    {R : Type u_3} → [inst : Semiring R] → (σ → M) → [inst_1 : AddCommMonoid M] → [Module R M] → (σ →₀ R) →+ M"
    },
    {
      "name": "Finsupp.le_weight_of_ne_zero'",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {M : Type u_4} [inst : AddCommMonoid M] [inst_1 : PartialOrder M] [IsOrderedAddMonoid M]\n  [CanonicallyOrderedAdd M] (w : σ → M) {s : σ} {f : σ →₀ ℕ}, f s ≠ 0 → w s ≤ (Finsupp.weight w) f"
    }
  ]
}
